1	// The app menu — the root of the stack: close button + Feed / Folders tabs
2	// on top (inline note + folder lists), Sync and Settings pinned at the
3	// bottom. The capture page sits pushed above it, so its hamburger or a
4	// left-edge swipe-back pops here; the close button or a right-edge leftward
5	// swipe pushes a fresh capture page back in. Everything else is pushed from
6	// here, so swipe-back from Sync/Settings/Folder/Editor lands back on the menu.
7	
8	import { CommonActions, useNavigation } from "@react-navigation/native";
9	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
10	import { useEffect, useState } from "react";
11	import {
12	  FlatList,
13	  InteractionManager,
14	  Pressable,
15	  SectionList,
16	  StyleSheet,
