          numberOfLines={1}
        >
          {value}
        </Text>
      ) : null}
      {checked ? (
        <Ionicons name="checkmark" size={19} color={theme.colors.accent} />
      ) : null}
      {chevron ? (
        <Ionicons
          name="chevron-forward"
          size={16}
          color={theme.colors.secondaryText}
          style={styles.chevron}
        />
      ) : null}
    </Pressable>
  );
};

/** A tappable row of accent text — the grouped-list equivalent of a button. */
export const SettingsActionRow = ({
  title,
  disabled,
  onPress,
}: {
  title: string;
  disabled?: boolean;
  onPress: () => void;
}) => {
  const theme = useTheme();
  return (
    <Pressable
      onPress={onPress}
      disabled={disabled}
      style={({ pressed }) => [
        styles.row,
        pressed && { backgroundColor: theme.dark ? "#ffffff14" : "#00000010" },
      ]}
    >
      <Text
        style={[
          styles.rowTitle,
          { color: theme.colors.accent, opacity: disabled ? 0.4 : 1 },
        ]}
      >
        {title}
      </Text>
    </Pressable>
  );
};

/** A text input living directly in a row, like iOS Settings' inline fields. */
export const SettingsFieldRow = (props: TextInputProps) => {
  const theme = useTheme();
  const { style, ...inputProps } = props;
  return (
    <View style={styles.row}>
      <TextInput
        placeholderTextColor={theme.colors.secondaryText}
        autoCapitalize="none"
        autoCorrect={false}
        {...inputProps}
        style={[styles.fieldInput, { color: theme.colors.text }, style]}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  group: { marginBottom: 28 },
  groupHeader: {
    fontSize: 13,
    marginBottom: 7,
    marginHorizontal: 16,
  },
  groupFooter: {
    fontSize: 13,
    lineHeight: 18,
    marginTop: 7,
    marginHorizontal: 16,
  },
  card: {
    borderRadius: 12,
    overflow: "hidden",
  },
  separator: { height: StyleSheet.hairlineWidth },
  row: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    minHeight: 44,
    paddingHorizontal: 16,
    paddingVertical: 9,
  },
  iconTile: {
    width: 29,
    height: 29,
    borderRadius: 6.5,
    alignItems: "center",
    justifyContent: "center",
  },
  rowText: { flex: 1, gap: 1 },
  rowTitle: { fontSize: 16 },
  rowSubtitle: { fontSize: 13 },
  rowValue: { fontSize: 16, flexShrink: 1 },
  chevron: { marginLeft: -6, opacity: 0.6 },
  fieldInput: { flex: 1, fontSize: 16, paddingVertical: 0 },
});

